from pathlib import Path
import re,json,hashlib
R=Path('terms/OT1998'); W=R/'close/holdings-work'
files=re.findall(r'\[record\]\(\.\./records/([^)]*)\)',(R/'workspace/ledger.md').read_text())[:24]
# Assignments below follow the adjudicated question, not the inventory label.
C='Constitutional Structure';F='Federal Courts';P='Criminal Procedure';V='Civil Rights';L='Labor and Employment';B='Business and Commercial Law';K='Bankruptcy';E='Property and Economic Rights';A='Antitrust'
areas={1:[C,V,V,C,V,P,P],2:[F,V,V,V],3:[F,F,C,V,V,V,V,C,C,C],4:[C]*3,5:[F]+[V]*10,6:[C,C]+[P]*6,7:[C,P,P],8:[L,L],9:[V]*4,10:[B],11:[B]*2,12:[F],13:[L],14:[F,E,E,E],15:[F]*2,16:[K]*2,17:[P]*3,18:[V]*3,19:[P]*2,20:[F],21:[F,K,K],22:[P]*4,23:[V],24:[A]*2}
auth={1:"Kennedy's opinion of the Court, joined in full by all eight Associate Justices; Stone-Zsela joins no part of the opinion.",2:"Souter's unanimous opinion of the Court.",3:"O'Connor's opinion of the Court, joined in full by all eight Associate Justices; Stone-Zsela agrees in the judgments without joining the opinion.",4:"The Court's unsigned supplemental decree, paragraphs 1–5 and its incorporated coordinate schedule; individual joins and a public tally are not announced.",5:"Thomas's opinion of the Court; O'Connor, Scalia, Kennedy, Souter, Ginsburg and Breyer join in full, and Stevens joins every part except Part IX. Eight direct joins support this proposition unless Part IX is specified.",6:"Ginsburg's opinion of the Court, joined in full by all eight Associate Justices; Stone-Zsela concurs in the judgments without joining the opinion.",7:"Chief Justice Stone-Zsela's unanimous opinion of the Court.",8:"Stevens's unanimous opinion of the Court.",9:"Breyer's opinion of the Court, Parts I, II and IV, joined by Stone-Zsela, Stevens, Souter and Ginsburg. Part III's Title VII holding is unanimous.",10:"Scalia's unanimous opinion of the Court.",11:"Kennedy's unanimous opinion of the Court; Stone-Zsela's additional primary-recklessness position is not part of the Court's holding.",12:"Scalia's unanimous opinion of the Court.",13:"Breyer's unanimous opinion of the Court.",14:"Stevens's opinion: Part I is unanimous; Parts II–IV are joined by all eight Associate Justices, with Stone-Zsela withholding assent to those federal merits grounds.",15:"Chief Justice Stone-Zsela's opinion of the Court, joined by Stevens, O'Connor, Kennedy, Souter, Ginsburg and Breyer (seven Justices).",16:"Souter's unanimous opinion of the Court.",17:None,18:"Ginsburg's opinion of the Court, joined by Stone-Zsela, Stevens, O'Connor, Kennedy, Souter and Breyer (seven Justices).",19:None,20:"The Court's reasoned per curiam disposition; no tally or individual lineup is announced.",21:"Thomas's unanimous opinion of the Court.",22:None,23:"Ginsburg's unanimous opinion of the Court.",24:"Scalia's unanimous opinion of the Court."}
limits={1:"No comprehensive arms scrutiny tier, closed weapons catalogue or categorical exclusion of dangerous arms is adopted. The statutory exceptions and registration limits stated below remain intact. The Court orders no acquittal, release, return of arms, new trial, automatic hearing, acceptance adjustment or particular sentence; the machinegun count and sentence return on their distinct grounds. A reserved legal challenge does not immunize false factual denials or other conduct inconsistent with actual acceptance.",2:"The holding concerns the developed official-use controversy, not every privately held weapon of a public employee. No universal arms-disability tier, individual conviction-classification or restoration ruling, private-possession application, or unresolved commerce or commandeering ground is decided. Section 928 does not authorize extending an exemption the developed objections do not invalidate.",3:"The case decides the preserved civil challenges and no criminal prosecution, notice or mental-state defense. No separate abandoned strict-scrutiny or procedural-due-process claim is revived; the local claims settled with prejudice stay closed. No individual conviction-relief entitlement, never-lost-rights construction or universal firearms disability is established.",4:"The complete coordinate schedule in the operative supplemental decree, paragraphs 1–5 (terms/OT1998/records/attachments/louisiana_supplemental_decree_1998-10-13.txt), is incorporated without abbreviation: every straight segment, arc center, endpoint, coordinate precision and sequence, zone and datum instruction controls. The map is illustrative. No new general coastal-ownership test or adjudication of another State's boundary follows.",5:"No substantive Second Amendment judgment, prosecution, automatic arrest authorization or new registration opportunity follows. No enforcement may rest independently on either invalid modification branch; valid definitions remain subject to the distinct enacted fault condition. Actual Ohio severability determines the conforming declaratory and injunctive relief.",6:"The two judgments are affirmed without remand. No arms claim is decided. The section 5K2.6 neighborhood alternative is not reached, and no categorical permission for neighborhood-, education-, employment- or drug-status departures is created. The reported flight consideration selects a term within the 51–63-month range; it supplies no new obstruction enhancement.",7:"Both judgments are affirmed, with no new trial, replacement instruction, remand or sentencing change. The constitutional basis, statutory nexus and proof of that nexus remain separate. No unpresented personal-arms claim, recipient mental-state rule or universal approval of every status restriction is decided.",8:"The distinct existing lower-court remands on actual enforcement and the unaddressed Beck-notice claim remain effective; neither claim is decided. The wording rule creates no safe harbor for misleading notice, nonchargeable collection or unlawful enforcement, and the grace-period claim cannot obtain a judicial basis from an unrelated pending claim.",9:"The judgment vacates and remands for confined preliminary protection, not a permanent entitlement to preferences or wholesale invalidation of Proposition 209. The exact restraint must follow the supported threatened injury, ordinary preliminary-relief requirements and state severability. The sex theory and any concrete conflict with federal duties receive their own adjudication.",10:"Both precritical-date conditions must be proved for the actual claimed invention; commercial commitment cannot supply an incomplete conception, and later development cannot retroactively establish readiness. Mere preliminary negotiations and future inventive research do not suffice. Genuine controlled experimentation remains distinct, and no experimental-use dispute is decided. The reviewed invalidity judgment is affirmed without invalidating unidentified claims.",11:"The knowing-deception theory alone controls; no general primary-fraud recklessness rule is established. The rule mandates no venue, universal quotation search or best possible price. Later execution regulations are not applied retroactively, though reliable retrospective evidence may illuminate contemporary feasibility. All private-action elements, class-certification issues and actual damages remain to be adjudicated.",12:"Neither standing nor its absence is found. No hearing, discovery, production or amendment entitlement is ordered. Both election-financing and optional-statement constitutional merits remain unadjudicated; no indigent-candidate, compulsory filing-fee, racial-intent or viewpoint-discrimination holding follows, and unpreserved state-law claims are not revived.",13:"The judgment vacates the exhaustion dismissal and returns the ADA claim for ordinary proceedings unless another independently lawful ground disposes of it. Neither instrument supports compelled arbitration. Explicit union-waiver enforceability, general FAA coverage, the ADA merits, qualifications and independent defenses remain undecided.",14:"The preclusive finding concerns profitable timber use, not every federal element or a precise residual valuation. The judgment is affirmed on the eight-Justice independent federal grounds; no permit, compensation or jury trial is ordered. Later permission limits duration and is not a retrospective cure for an otherwise proved taking.",15:"The Court neither finds standing nor affirms the District Court's standing determination; it does not decide Pullman abstention or invalidate Wisconsin law. Official and independent private enforcement have distinct causal and remedial requirements. Contested merits remain for proper consideration only after the necessary Article III inquiry.",16:"No gambling exemption or conclusive acceptance of a debtor's asserted intent follows. Actual and recipient-specific justifiable reliance, causation and debt extent remain independent and undecided. Section 523(a)(2)(A) excludes financial-condition statements; subsection (B)'s written-statement, material-falsity, reasonable-reliance and intentional-publication conditions remain distinct. Other representation theories, subsection (C)'s recent-debt presumption and §523(d) fees are not adjudicated.",17:"Each respondent's personal privacy interest is independently established; Carter's disputed key proffer supplies no fact for Johns and is not adjudicated. Neither all evidence admission nor all evidence exclusion follows. No hearing, discovery, photographic reconstruction, new factual-review standard, burden shift or general curtilage rule is created.",18:"No suspect classification, orientation-based strict scrutiny, general fundamental right of political access or overruling of Bowers is adopted. No particular municipal code or damages is ordered. Injunction terms must respect an independently lawful severable remainder, and restored prevailing-party status fixes no §1988 amount.",19:"The constitutional rule is unanimous. The eight-Associate remedial return does not adopt Stone-Zsela's separate automatic suppression direction. No alternative search ground is established; independent protective measures, consent and probable-cause grounds retain their own predicates. No acquittal, release, replacement sentence or civil liability is ordered.",20:"Only the grant and petition are disposed of; the Third Circuit judgment remains undisturbed without endorsement. No bank-robbery/bank-larceny elements holding, indictment dismissal or automatic abatement follows. Death during appeal of right, substituted estate litigation, fines, restitution and independent collateral consequences remain undecided.",21:"The valid lien and discharged personal liability retain separate consequences. No default, foreclosure, repossession or substitute agreement is ordered, and no general invalidity of bankruptcy clauses is decided. Section 521(2) does not itself excuse an actual default or authorize lien stripping or installment redemption.",22:"The accuracy of the commutation instruction is assumed for the presented effect question, not independently decided; the error is trial error and does not warrant automatic structural relief. Guilt remains undisturbed. No actual harmlessness, automatic writ denial, evidence admission, new hearing, deadline, immediate release, execution or stay is ordered. Other penalty claims retain their actual appellate status, and independent habeas conditions remain effective.",23:"The judgment rejects the categorical constitutional-property ground, leaving conspiracy, prohibited purpose, federal-witness nexus, acts, causation, damages and properly presented defenses for decision. No constitutional tenure, general federal wrongful-discharge action or corporate-agent conspiracy ruling is created.",24:"The District Court's wholesale dismissal is not automatically reinstated. The distinct §2 conspiracy requirements remain, while previously dismissed vertical-price-fixing, monopolization, attempt and RICO claims are not revived. The Court finds neither competitive injury nor harmlessness and grants neither immunity for fraud nor a final damages or injunction remedy."}
entries=[];cov=[]
for idx,f in enumerate(files,1):
 s=(R/'records'/f).read_text();p=s.split('## Public Projection',1)[1]
 h=p.split('## Holdings',1)[1].split('## Precedent Treatment',1)[0].strip()
 title=s.splitlines()[0].split('**Case and dockets:** ',1)[1]
 date=re.search(r'199[89]-\d\d-\d\d',s.splitlines()[1]).group()
 # Case identity and all supplied dockets retained without pretending a lower citation is a Supreme Court citation.
 first=title.split(';')[0].split(', No.')[0]
 if ', No.' in first: first=first.split(', No.')[0]
 if 'reported at ' in title:
  first+=', '+title.split('reported at ')[1].rstrip('.')
 rawcase=title.split(';')[0].split(', No.')[0]
 dockets=title[len(rawcase):].lstrip(',; ')
 dockets=re.sub(r'; reported at .*$', '', dockets)
 identity=f'#### {first}\n\n**Docket or dockets:** {dockets}\n**Decided:** {date}.\n\n'
 chunks=[ch for ch in re.split(r'^### ',h,flags=re.M)[1:] if not ch.startswith(('Statutory scope retained throughout','Statutory qualifications governing these holdings'))]
 if idx==20: chunks=['Effect of death on this personal criminal certiorari proceeding\n\n'+h]
 if len(chunks)!=len(areas[idx]):raise ValueError((idx,len(chunks),areas[idx]))
 groups={}
 for j,ch in enumerate(chunks):
  head,body=ch.split('\n',1);head=re.sub(r'^(?:[IVX]+(?:-[AB])?|\d+)\.\s*','',head)
  # These headings identify retained source-wide qualifications, not an additional judicial question.
  if head in ['Statutory scope retained throughout','Statutory qualifications governing these holdings']:raise ValueError('scope counted')
  if idx==17 and j==2:
   question='##### Whether the judgment establishes a controlling actual-search application\n\n**Authority of the judgment:** '+body.strip().replace('**Judgment without controlling search rationale:** ','')+'\n'
  else:
   paras=[x.strip() for x in body.strip().split('\n\n') if x.strip()]
   rule=next((x for x in paras if re.match(r'\*\*(?:Holding and operative rule:|Operative rule[:.]|Rule:)',x)),None)
   if not rule: raise ValueError((idx,j,'no rule'))
   rule=re.sub(r'^\*\*[^*]+\*\*\s*','',rule)
   rawauth=next((x for x in paras if re.match(r'\*\*Authority[:.]',x)),None)
   authority=auth[idx]
   if idx in (17,19,22):authority=re.sub(r'^\*\*[^*]+\*\*\s*','',rawauth)
   elif idx==5 and j==8:authority="Thomas's opinion of the Court, Part IX, joined by O'Connor, Scalia, Kennedy, Souter, Ginsburg and Breyer (seven Justices). Stevens and Stone-Zsela do not join this proposition."
   elif idx==9: authority="Breyer's unanimous opinion of the Court, Part III." if j==2 else "Breyer's opinion of the Court, joined by Stone-Zsela, Stevens, Souter and Ginsburg (five Justices)."
   elif idx==14:authority="Stevens's unanimous opinion of the Court, Part I." if j==0 else f"Stevens's opinion of the Court, Part {['I','II','III','IV'][j]}, joined by all eight Associate Justices; Stone-Zsela does not join."
   question=f'##### {head}\n\n**Holding:** {rule}\n\n**Proposition-level authority:** {authority}\n'
   for para in paras:
    if re.match(r'\*\*(Operative qualifications|Remedy and limits|Remand limits and questions not reached|Complete section 5 exceptions):',para):
     question+='\n**Limits and questions not reached:** '+re.sub(r'^\*\*[^*]+\*\*\s*','',para)+'\n'
    elif para.startswith('**Precedent treatment:**'):
     question+='\n**Treatment of earlier authority:** '+para.split('**Precedent treatment:**',1)[1].strip()+'\n'
  groups.setdefault(areas[idx][j],[]).append(question)
 # Global statutory qualifications: retain exact operative restrictions under the principal substantive area.
 scope=''
 for heading in ['### Statutory scope retained throughout','### Statutory qualifications governing these holdings']:
  if heading in h:scope=h.split(heading,1)[1].strip()
 if idx==9:
  scope=h.split('**Operative statutory limits:**',1)[1].strip()
 primary=next((a for a in groups if a!=F),next(iter(groups)))
 treatment=p.split('## Precedent Treatment',1)[1].split('## Law After Decision',1)[0].strip()
 for area,qs in groups.items():
  text=identity+'\n'.join(qs)+'\n**Limits and questions not reached:** '+limits[idx]+'\n'
  if area==primary:
   if scope:text+='\n**Limits and questions not reached:** '+scope+'\n'
   text+='\n**Treatment of earlier authority:**\n\n'+treatment+'\n'
  if len(groups)>1:
   others=[a for a in groups if a!=area]
   text+='\nFor the other questions in '+first+', decided '+date+', '+dockets+', see '+', '.join(others)+'.\n'
  entries.append({'file':f,'area':area,'text':text,'status':'include'})
 cov.append({'file':f,'date':date,'status':'include','areas':list(groups),'questions':len(chunks),'source_sha256':hashlib.sha256(s.encode()).hexdigest()})
(W/'chunk12_entries.json').write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n')
(W/'chunk12_coverage.json').write_text(json.dumps(cov,ensure_ascii=False,indent=2)+'\n')
print('records',len(cov),'area entries',len(entries),'questions',sum(x['questions'] for x in cov))
